// Texts, Google Sheet column names and node names used below. Edit the texts here.
const T = {
  "locale": "en-US",
  "nodes": {
    "config": "Config",
    "rpReadListings": "Read listings",
    "rpReadLeads": "Read leads"
  },
  "cols": {
    "lead": {
      "id": "Lead ID",
      "lastEnquiry": "Last Enquiry At",
      "name": "Name",
      "email": "Email",
      "phone": "Phone",
      "intent": "Intent",
      "propertyRef": "Property Ref",
      "budget": "Budget",
      "timeline": "Timeline",
      "areas": "Preferred Areas",
      "minBeds": "Min Bedrooms",
      "propertyType": "Property Type",
      "message": "Message",
      "source": "Source",
      "score": "Score",
      "temperature": "Temperature",
      "status": "Status",
      "step": "Follow-up Step",
      "lastContact": "Last Contact At",
      "nextFollowUp": "Next Follow-up At",
      "notes": "Notes"
    },
    "listing": {
      "ref": "Listing Ref",
      "address": "Address",
      "city": "City",
      "price": "Price",
      "beds": "Bedrooms",
      "propertyType": "Property Type",
      "listingType": "Listing Type",
      "status": "Status",
      "listedAt": "Listed At",
      "url": "Listing URL",
      "sellerName": "Seller Name",
      "sellerEmail": "Seller Email",
      "alertSentAt": "Alert Sent At",
      "lastReportAt": "Last Report Sent At"
    },
    "viewing": {
      "id": "Viewing ID",
      "listingRef": "Listing Ref",
      "buyerName": "Buyer Name",
      "buyerEmail": "Buyer Email",
      "buyerPhone": "Buyer Phone",
      "start": "Start",
      "end": "End",
      "status": "Status",
      "eventId": "Calendar Event ID",
      "reminderAt": "Reminder Sent At",
      "rating": "Feedback Rating",
      "comment": "Feedback Comment",
      "createdAt": "Created At"
    }
  },
  "values": {
    "intent": {
      "buy": "buy",
      "sell": "sell",
      "rent": "rent",
      "other": "other"
    },
    "timeline": {
      "soon": "0-3 months",
      "mid": "3-6 months",
      "later": "6+ months",
      "unknown": "unknown"
    },
    "temp": {
      "hot": "Hot",
      "warm": "Warm",
      "cold": "Cold"
    },
    "leadStatus": {
      "new": "New",
      "contacted": "Contacted"
    },
    "listingStatus": {
      "available": "Available"
    },
    "listingType": {
      "sale": "Sale",
      "rent": "Rent"
    },
    "viewingStatus": {
      "booked": "Booked",
      "done": "Done",
      "cancelled": "Cancelled"
    }
  },
  "text": {
    "report": {
      "subject": "Your weekly property report — {from} to {to}",
      "fromFormat": "d LLL",
      "toFormat": "d LLL yyyy",
      "ref": "Ref {ref}",
      "greeting": "<p>Hi {firstName},</p>",
      "greetingNoName": "<p>Hi there,</p>",
      "intro": "<p>Here is what happened on your {what} over the last {days} days.</p>",
      "property": "property",
      "properties": "properties",
      "price": "{currency}{amount}",
      "daysOnMarket": " · {days} days on the market",
      "rows": {
        "enquiries": "New enquiries (this week / total)",
        "viewings": "Viewings (this week / total)",
        "upcoming": "Upcoming viewings",
        "rating": "Average viewer rating"
      },
      "comments": "<p><i>What viewers said:</i></p>",
      "advice": {
        "followUp": "Plenty of interest this week but no viewings yet — we are following up with every enquirer to book visits.",
        "mixed": "Viewer feedback is mixed. It may be worth reviewing presentation or price together.",
        "stale": "Activity has slowed down. A price review or refreshed photos could relaunch interest.",
        "upcomingOne": "1 viewing already booked for the coming days.",
        "upcomingMany": "{n} viewings already booked for the coming days.",
        "steady": "Steady activity — no change recommended this week."
      },
      "outro": "<p>Any questions? Just reply to this email.</p><p>Best regards,<br>{agentName}<br>{agency}</p>"
    }
  }
};

// Build one weekly activity report per seller (all of their active listings in one email).
// Helpers (texts and column names live in the T object above — edit them there).
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fill = (tpl, vars) => String(tpl).replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined ? vars[k] : m));
const greet = (tpl, name) => (String(name || '').trim()
  ? fill(tpl.greeting, { firstName: esc(String(name).trim().split(' ')[0]) })
  : tpl.greetingNoName);
// Internal key from a cell value: accepts the key itself ("buy") or the label of this language ("Buy", "achat").
const keyOf = (map, label) => {
  const l = String(label ?? '').trim().toLowerCase();
  for (const [k, v] of Object.entries(map)) if (l === k || l === String(v).toLowerCase()) return k;
  return null;
};
const money = (n) => new Intl.NumberFormat(T.locale, { maximumFractionDigits: 0 }).format(n);
const isEmail = (v) => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(String(v || '').trim());
const config = $(T.nodes.config).first().json;
const L = T.cols.listing;
const P = T.cols.lead;
const W = T.cols.viewing;
const X = T.text.report;
const tz = config.timezone;
const now = DateTime.now().setZone(tz);
const since = now.minus({ days: Number(config.reportDays) || 7 });
const dt = (v) => { const d = DateTime.fromISO(String(v ?? ''), { setZone: true }); return d.isValid ? d : null; };
const rows = (node) => $(node).all().map((i) => i.json).filter((r) => Object.keys(r).length);
const num = (v) => Number(String(v ?? '').replace(/[^\d.]/g, '') || 0);

const activeStatuses = String(config.reportStatuses).split(',').map((s) => s.trim().toLowerCase());
const listings = rows(T.nodes.rpReadListings).filter((l) =>
  l[L.ref] && activeStatuses.includes(String(l[L.status] || '').toLowerCase()) && isEmail(l[L.sellerEmail]));
const leads = rows(T.nodes.rpReadLeads);
const viewings = $input.all().map((i) => i.json).filter((r) => Object.keys(r).length);

const statsFor = (l) => {
  const ref = String(l[L.ref]);
  const enquiries = leads.filter((x) => String(x[P.propertyRef]) === ref);
  const vs = viewings.filter((v) => String(v[W.listingRef]) === ref && keyOf(T.values.viewingStatus, v[W.status]) !== 'cancelled');
  const inPeriod = (d) => d && d >= since && d <= now;
  const done = vs.filter((v) => { const s = dt(v[W.start]); return s && s <= now; });
  const rated = done.filter((v) => Number(v[W.rating]) > 0);
  const listed = dt(l[L.listedAt]);
  return {
    l,
    enquiriesWeek: enquiries.filter((x) => inPeriod(dt(x[P.lastEnquiry]))).length,
    enquiriesTotal: enquiries.length,
    viewingsWeek: done.filter((v) => inPeriod(dt(v[W.start]))).length,
    viewingsTotal: done.length,
    upcoming: vs.filter((v) => { const s = dt(v[W.start]); return s && s > now; }).length,
    avgRating: rated.length ? rated.reduce((a, v) => a + Number(v[W.rating]), 0) / rated.length : null,
    comments: done.filter((v) => inPeriod(dt(v[W.start])) && v[W.comment]).map((v) => String(v[W.comment])),
    daysOnMarket: listed ? Math.max(0, Math.floor(now.diff(listed, 'days').days)) : null,
  };
};

// Plain-language advice from simple, transparent rules.
const advice = (s) => {
  if (s.enquiriesWeek >= 3 && s.viewingsWeek === 0) return X.advice.followUp;
  if (s.viewingsTotal >= 5 && s.avgRating !== null && s.avgRating < 3) return X.advice.mixed;
  if ((s.daysOnMarket ?? 0) > Number(config.staleAfterDays) && s.enquiriesWeek === 0) return X.advice.stale;
  if (s.upcoming === 1) return X.advice.upcomingOne;
  if (s.upcoming > 1) return fill(X.advice.upcomingMany, { n: s.upcoming });
  return X.advice.steady;
};

const rating = (s) => (s.avgRating === null ? '—' : s.avgRating.toLocaleString(T.locale, { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + ' / 5');
const section = (s) => `<h3 style="margin:24px 0 4px">${esc(s.l[L.address])}, ${esc(s.l[L.city])}</h3>
<p style="margin:0;color:#666">${fill(X.ref, { ref: esc(s.l[L.ref]) })} · ${fill(X.price, { currency: esc(config.currencySymbol), amount: money(num(s.l[L.price])) })} · ${esc(s.l[L.status])}${s.daysOnMarket !== null ? fill(X.daysOnMarket, { days: s.daysOnMarket }) : ''}</p>
<table style="border-collapse:collapse;margin:8px 0">
<tr><td style="padding:4px 16px 4px 0">${X.rows.enquiries}</td><td><b>${s.enquiriesWeek}</b> / ${s.enquiriesTotal}</td></tr>
<tr><td style="padding:4px 16px 4px 0">${X.rows.viewings}</td><td><b>${s.viewingsWeek}</b> / ${s.viewingsTotal}</td></tr>
<tr><td style="padding:4px 16px 4px 0">${X.rows.upcoming}</td><td><b>${s.upcoming}</b></td></tr>
<tr><td style="padding:4px 16px 4px 0">${X.rows.rating}</td><td><b>${rating(s)}</b></td></tr>
</table>
${s.comments.length ? `${X.comments}<ul>${s.comments.map((c) => `<li>${esc(c)}</li>`).join('')}</ul>` : ''}
<p style="background:#f5f7fa;padding:8px 12px;border-radius:6px">💡 ${esc(advice(s))}</p>`;

const bySeller = {};
for (const l of listings) {
  const key = String(l[L.sellerEmail]).trim().toLowerCase();
  (bySeller[key] = bySeller[key] || []).push(statsFor(l));
}

const vars = { agentName: esc(config.agentName), agency: esc(config.agencyName) };
return Object.entries(bySeller).map(([to, stats]) => ({
  json: {
    to,
    listingRefs: stats.map((s) => s.l[L.ref]),
    subject: fill(X.subject, { from: since.setLocale(T.locale).toFormat(X.fromFormat), to: now.setLocale(T.locale).toFormat(X.toFormat) }),
    html: `${greet(X, stats[0].l[L.sellerName])}${fill(X.intro, { what: stats.length > 1 ? X.properties : X.property, days: Number(config.reportDays) || 7 })}
${stats.map(section).join('')}
${fill(X.outro, vars)}`,
  },
}));

